// Species table for the visualization study's multi-variable stages. Generated
// offline from the occurrence data. A species is listed when it has 2,000-5,000
// observations (not obscured, <= 500 m coordinate uncertainty) and all but
// <= 1% of them fit one 800x480 px map window at zoom 4 (`viewBox`; only
// observations inside it are displayed and scored - a purely geographic crop).
// Per study variable, the statistics are over the displayed observations that
// have a value for it, in the units the study displays (imperial: F for bio1,
// inches for bio12):
//   nv        number of displayed observations with a value
//   mean      mean over those observations
//   cellMean  mean over occupied map cells (each place counted once)
//   spread    max - min
//   relativeMean  (mean - min) / (max - min): where the mean sits in its own range
// `entropy`: normalized (0-1) Shannon entropy of where the displayed
// observations fall across the window's 16x16 cells (low = clustered).
// Species whose window crosses the antimeridian are excluded.

import type { StudyVariableId } from '@/components/sections/studyVariables';

export type StudyViewBox = {
  lonMin: number;
  lonMax: number;
  latMin: number;
  latMax: number;
};

export type VariableStats = {
  nv: number;
  mean: number;
  cellMean: number;
  spread: number;
  /** (mean - min) / (max - min) of the displayed values: where the mean sits
   * within the species' own range (0 = at the min, 1 = at the max). */
  relativeMean: number | null;
};

export type StageSpecies = {
  id: string;
  name: string;
  n: number;
  entropy: number;
  viewBox: StudyViewBox;
  stats: Partial<Record<StudyVariableId, VariableStats>>;
};

/** Per variable, over the species with enough values: the standard deviation of
 * the species means, and the median / 75th percentile of the spreads. The
 * selection rules are expressed in these so they transfer across variables. */
export const VARIABLE_POPULATION: Record<
  StudyVariableId,
  { sdMeans: number; spreadMedian: number; spreadP75: number }
> = {
  bio1: { sdMeans: 9.3, spreadMedian: 24.84, spreadP75: 30.42 },
  bio12: { sdMeans: 22.19, spreadMedian: 66.21, spreadP75: 105.1 },
  rsdsmean: { sdMeans: 25.96, spreadMedian: 66.0, spreadP75: 90.0 },
  scdur: { sdMeans: 49.71, spreadMedian: 115.3, spreadP75: 203.1 },
  cfvo: { sdMeans: 4.882, spreadMedian: 24.6, spreadP75: 31.4 },
};

type Cell = [number, number, number, number, number | null] | null;
// id, name, n, entropy, lonMin, lonMax, latMin, latMax, then one Cell per
// variable in STAGE_VARIABLE_ORDER.
type Raw = [
  string,
  string,
  number,
  number,
  number,
  number,
  number,
  number,
  ...Cell[],
];

const STAGE_VARIABLE_ORDER: StudyVariableId[] = [
  'bio1',
  'bio12',
  'rsdsmean',
  'scdur',
  'cfvo',
];

