export const STAGE_SPECIES: StageSpecies[] = RAW.map((row) => {
  const [id, name, n, entropy, lonMin, lonMax, latMin, latMax, ...cells] = row;
  const stats: StageSpecies['stats'] = {};
  STAGE_VARIABLE_ORDER.forEach((variable, i) => {
    const cell = cells[i];
    if (cell) {
      stats[variable] = {
        nv: cell[0],
        mean: cell[1],
        cellMean: cell[2],
        spread: cell[3],
        relativeMean: cell[4],
      };
    }
  });
  return {
    id,
    name,
    n,
    entropy,
    viewBox: { lonMin, lonMax, latMin, latMax },
    stats,
  };
});
